INSERT INTO news (title, excerpt, content, category, is_featured, image_url) VALUES
  ('UK Muslims celebrate Eid across the country', 'Millions of Muslims across the United Kingdom celebrated Eid with prayers, community gatherings, and festivities in cities and towns.', 'Millions of Muslims across the United Kingdom celebrated Eid with prayers, community gatherings, and festivities in cities and towns. From London to Glasgow, mosques were filled with worshippers attending special Eid prayers, followed by family gatherings, community meals, and charity events.', 'uk', true, 'https://images.pexels.com/photos/3279132/pexels-photo-3279132.jpeg?auto=compress&cs=tinysrgb&w=800'),
  ('New Islamic Centre opens in Birmingham city centre', 'A new purpose-built Islamic Centre has opened its doors in Birmingham, providing prayer facilities and educational programmes.', 'A new purpose-built Islamic Centre has opened its doors in Birmingham, providing prayer facilities and educational programmes for the local community. The centre features a main prayer hall, classrooms, and community spaces.', 'local', false, 'https://images.pexels.com/photos/3886488/pexels-photo-3886488.jpeg?auto=compress&cs=tinysrgb&w=800'),
  ('Ramadan 2026: Community iftar guide across the UK', 'Communities across the UK are hosting a variety of iftar events this Ramadan. From free community iftars at mosques to charity fundraising dinners.', 'Communities across the UK are hosting a variety of iftar events this Ramadan. From free community iftars at mosques to charity fundraising dinners, there are opportunities for everyone to participate in the blessed month.', 'community', false, 'https://images.pexels.com/photos/6646917/pexels-photo-6646917.jpeg?auto=compress&cs=tinysrgb&w=800'),
  ('Muslim charity raises £2m for global humanitarian relief', 'A UK-based Muslim charity has announced a record-breaking fundraising campaign, raising over £2 million for communities affected by humanitarian crises.', 'A UK-based Muslim charity has announced a record-breaking fundraising campaign, raising over £2 million for communities affected by humanitarian crises worldwide. The funds will support emergency relief, food programmes, and long-term development projects.', 'uk', true, 'https://images.pexels.com/photos/6646917/pexels-photo-6646917.jpeg?auto=compress&cs=tinysrgb&w=800'),
  ('Islamic finance sector continues to grow in the UK', 'The Islamic finance sector continues to expand with new halal mortgage products and shariah-compliant savings accounts being launched by major UK banks.', 'The Islamic finance sector continues to expand with new halal mortgage products and shariah-compliant savings accounts being launched by major UK banks. The sector has seen sustained growth as demand for ethical, faith-based financial products increases.', 'uk', false, 'https://images.pexels.com/photos/4386321/pexels-photo-4386321.jpeg?auto=compress&cs=tinysrgb&w=800'),
  ('Youth Islamic education programme launches nationwide', 'A new nationwide Islamic education programme targeting young Muslims aged 11-18 has launched across 50 UK cities, offering weekend classes and mentorship.', 'A new nationwide Islamic education programme targeting young Muslims aged 11-18 has launched across 50 UK cities, offering weekend classes and mentorship. The programme aims to provide accessible Islamic education alongside academic support.', 'community', false, 'https://images.pexels.com/photos/5212345/pexels-photo-5212345.jpeg?auto=compress&cs=tinysrgb&w=800')
